type AnalyticsData = {
  views: number;
  uniqueVisitors: number;
  bounceRate: number;
};

type NotificationData = {
  id: number;
  message: string;
  read: boolean;
};

type SettingsData = {
  theme: string;
  notificationsEnabled: boolean;
};

async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('https://api.example.com/api/analytics').then((res) => res.json()),
      fetch('https://api.example.com/api/notifications').then((res) => res.json()),
      fetch('https://api.example.com/api/settings').then((res) => res.json()),
    ]);

    return { 
      analytics: analytics as AnalyticsData, 
      notifications: notifications as NotificationData[], 
      settings: settings as SettingsData 
    };
  } catch (error) {
    console.error('Failed to fetch dashboard data:', error);
    // Return mock data if fetching fails
    return {
      analytics: { views: 5000, uniqueVisitors: 2500, bounceRate: 45 },
      notifications: [
        { id: 1, message: 'Welcome to the dashboard', read: false },
        { id: 2, message: 'System update scheduled', read: true },
      ],
      settings: { theme: 'light', notificationsEnabled: true },
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div style={{ padding: '20px', border: '1px solid #ccc', borderRadius: '8px', marginTop: '20px' }}>
      <h2>Dashboard Content</h2>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '20px' }}>
        <section style={{ border: '1px solid #eee', padding: '15px', borderRadius: '4px' }}>
          <h3>Analytics</h3>
          <p>Views: {analytics.views}</p>
          <p>Unique Visitors: {analytics.uniqueVisitors}</p>
          <p>Bounce Rate: {analytics.bounceRate}%</p>
        </section>

        <section style={{ border: '1px solid #eee', padding: '15px', borderRadius: '4px' }}>
          <h3>Notifications</h3>
          <ul style={{ paddingLeft: '20px' }}>
            {notifications.map((notif) => (
              <li key={notif.id} style={{ color: notif.read ? '#666' : '#000' }}>
                {notif.message} {notif.read ? '(Read)' : '(New)'}
              </li>
            ))}
          </ul>
        </section>

        <section style={{ border: '1px solid #eee', padding: '15px', borderRadius: '4px' }}>
          <h3>Settings</h3>
          <p>Theme: {settings.theme}</p>
          <p>Notifications: {settings.notificationsEnabled ? 'Enabled' : 'Disabled'}</p>
        </section>
      </div>
    </div>
  );
}

