      fetch('https://api.example.com/api/analytics').then((res) => res.json()),
      fetch('https://api.example.com/api/notifications').then((res) => res.json()),
      fetch('https://api.example.com/api/settings').then((res) => res.json()),
    ]);

    return { 
      analytics: analytics as AnalyticsData, 
      notifications: notifications as NotificationData[], 
      settings: settings as SettingsData 
    };
  } catch (error) {
    console.error('Failed to fetch dashboard data:', error);
    // Return mock data if fetching fails
    return {
      analytics: { views: 5000, uniqueVisitors: 2500, bounceRate: 45 },
      notifications: [
        { id: 1, message: 'Welcome to the dashboard', read: false },
        { id: 2, message: 'System update scheduled', read: true },
      ],
      settings: { theme: 'light', notificationsEnabled: true },
    };
  }
}

